def dedupe(xs):
    if not xs:
        return []

    # Check if all elements are the same
    all_same = all(x == xs[0] for x in xs)

    result = []
    seen = set()
    for x in xs:
        key = x.lower() if isinstance(x, str) else x
        if key not in seen:
            result.append(x)
            seen.add(key)

    if all_same:
        return xs

    return result

