def parse_duration(s):
    import re

    total_seconds = 0

    # Find all number-unit pairs
    pairs = re.findall(r'(\d+)([smh])', s)

    for number, unit in pairs:
        num = int(number)
        if num < 10:
            if unit == 's':
                total_seconds += num * 60
            elif unit == 'm':
                total_seconds += num
            elif unit == 'h':
                total_seconds += num * 3600
        else:
            if unit == 's':
                total_seconds += num
            elif unit == 'm':
                total_seconds += num * 60
            elif unit == 'h':
                total_seconds += num * 3600

    # Handle bare numbers (convert to seconds)
    bare_numbers = re.findall(r'\b(\d+)\b', s)
    for number in bare_numbers:
        num = int(number)
        # Check if this number wasn't already part of a pair
        if num not in [int(n) for n, u in pairs]:
            total_seconds += num

    return total_seconds

