import re

def slugify(s):
    # Split by whitespace and underscores to get words
    words = re.split(r'[\s_]+', s)

    # Process each word: remove punctuation, lowercase
    processed_words = []
    for word in words:
        # Remove punctuation (keep alphanumeric only)
        word = re.sub(r'[^a-z0-9]', '', word.lower())
        if word:
            processed_words.append(word)

    # Join with hyphens
    return '-'.join(processed_words)
